code:
variable "environment" {
  type = string
}

variable "vnet_address_space" {
  type = list(string)
}

variable "subnet_count" {
  type = number
}

variable "subnet_newbits" {
  type    = number
  default = 8
}

resource "azurerm_subnet" "this" {
  count                = var.subnet_count
  name                 = "snet-cra-${var.environment}-${count.index}"
  resource_group_name  = azurerm_resource_group.network.name
  virtual_network_name = azurerm_virtual_network.this.name
  address_prefixes = [
    cidrsubnet(var.vnet_address_space[0], var.subnet_newbits, count.index)
  ]
}

output "vnet_id" {
  value = azurerm_virtual_network.this.id
}

output "subnet_ids" {
  value = azurerm_subnet.this[*].id
}

output "resource_group_name" {
  value = azurerm_resource_group.network.name
}

terraform {
  backend "azurerm" {
    resource_group_name  = "rg-cra-tfstate"
    storage_account_name = "stcratfstate"
    container_name       = "tfstate"
    key                  = "network/dev.tfstate"
  }
}

module "network" {
  source             = "../../modules/network"
  environment        = "dev"
  vnet_address_space = ["10.10.0.0/20"]
  subnet_count       = 2
}
